        String artistText = a.artist != null && !a.artist.trim().isEmpty()
                ? a.artist
                : h.itemView.getContext().getString(R.string.unknown_artist);
        h.title.setText(artistText);
        h.subtitle.setText(a.name != null ? a.name : "");
